/**
 * Soft v8b SoT host document — CSS preserve-3d + gas-svg + idle PNG data URL.
 * Mirrors assets/brand/soft-v8b-host.html. SoftMark injects --s + .is-on.
 */
export const SOFT_V8B_HOST_HTML = `<!DOCTYPE html>
<!-- soft-v8b-host: Soft v8b SoT avatar host (DOM/WebView) -->
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"/>
<style>
  html,body{margin:0;padding:0;background:transparent;overflow:hidden;width:100%;height:100%;}
  .av{
    --s:64px;
    --letter-h:calc(var(--s) * 468 / 512);
    --orbit-r:calc(var(--letter-h) * 0.41);
    --gimbal:calc(var(--letter-h) * 1.44);
    --ball:calc(var(--letter-h) * 0.08);
    width:var(--s);height:var(--s);position:relative;
    transform-style:preserve-3d;
  }
  .scene{
    width:100%;height:100%;position:relative;
    transform-style:preserve-3d;
  }
  .idle-png{
    position:absolute;inset:0;width:100%;height:100%;
    object-fit:contain;display:block;pointer-events:none;
    user-select:none;-webkit-user-drag:none;
  }
  .breathe{
    position:absolute;inset:0;
    transform-style:preserve-3d;
    transform-origin:50% 54%;
  }
  .av.is-on .breathe{
    animation:breathe 1.7s ease-in-out infinite;
  }
  @keyframes breathe{
    0%,100%{transform:rotate(-1.2deg);}
    50%{transform:rotate(1.6deg);}
  }
  .wobble{
    position:absolute;inset:0;
    transform-style:preserve-3d;
    transform-origin:50% 55%;
  }
  .av.is-on .wobble{
    animation:wobble 1.7s ease-in-out infinite;
  }
  @keyframes wobble{
    0%,100%{transform:rotate(-2.2deg);}
    50%{transform:rotate(2.6deg);}
  }
  .face{
    position:absolute;inset:0;width:100%;height:100%;
    overflow:visible;pointer-events:none;
    opacity:0;transform:scale(0.35);
    transform-origin:45% 42%;
    transition:opacity 280ms cubic-bezier(0.22,1,0.36,1), transform 280ms cubic-bezier(0.22,1,0.36,1);
  }
  .av.is-on .face{
    opacity:1;transform:scale(1);
  }
  .look{
    transform-box:fill-box;transform-origin:center;
  }
  .av.is-on .look{
    animation:glance 8s ease-in-out infinite;
  }
  @keyframes glance{
    0%,12%{transform:translate(0,0);}
    18%,30%{transform:translate(3.2%,0.4%);}
    36%,48%{transform:translate(0,0);}
    54%,66%{transform:translate(-2.8%,-2.2%);}
    72%,84%{transform:translate(3.2%,0.4%);}
    90%,100%{transform:translate(0,0);}
  }
  .lid{
    transform-box:fill-box;transform-origin:center;
    transform:scaleY(0);
    transition:transform 90ms ease-out;
  }
  .av.is-on .lid{
    transform:scaleY(1);
    animation:blink 4.4s ease-in-out infinite;
  }
  @keyframes blink{
    0%,90%,100%{transform:scaleY(1);}
    93%,95%{transform:scaleY(0.06);}
  }
  .mouth{
    transform-box:fill-box;transform-origin:center;
    opacity:0;transform:scale(0.12,0.15);
    transition:opacity 280ms ease-out, transform 280ms ease-out;
  }
  .av.is-on .mouth{
    opacity:1;transform:scale(1,1);
  }
  .gimbal{
    position:absolute;
    left:calc(50% - var(--gimbal) / 2);
    top:calc(50% - var(--gimbal) / 2);
    width:var(--gimbal);height:var(--gimbal);
    transform:rotateZ(14deg) rotateX(26deg);
    transform-style:preserve-3d;
    opacity:0;
    transition:opacity 420ms cubic-bezier(0.22,1,0.36,1);
    pointer-events:none;
  }
  .av.is-on .gimbal{opacity:1;}
  .ring-spin{
    width:100%;height:100%;
    transform-style:preserve-3d;
  }
  .av.is-on .ring-spin{
    animation:yaw-rev 2.45s linear infinite;
  }
  @keyframes yaw-rev{
    to{transform:rotateY(-360deg);}
  }
  .gas-svg{
    position:absolute;inset:0;width:100%;height:100%;
    overflow:visible;
    transform-style:preserve-3d;
  }
  .billboard{
    position:absolute;
    left:50%;top:50%;
    width:var(--ball);height:var(--ball);
    margin-left:calc(var(--ball) / -2);
    margin-top:calc(var(--ball) / -2);
    border-radius:50%;
    background:radial-gradient(circle at 35% 30%,#E8FFFF 0%,#9AF7FF 45%,#4FD0E8 100%);
    box-shadow:0 0 calc(var(--ball)*0.6) rgba(154,247,255,0.85);
    transform:translateZ(var(--orbit-r));
    transform-style:preserve-3d;
  }
  @media (prefers-reduced-motion:reduce){
    .av.is-on .breathe,
    .av.is-on .wobble,
    .av.is-on .look,
    .av.is-on .lid,
    .av.is-on .ring-spin{
      animation:none !important;
    }
    .av.is-on .face,
    .av.is-on .mouth,
    .av.is-on .gimbal{
      transition:none !important;
    }
  }
</style>
</head>
<body>
  <div class="av" id="soft-root">
    <div class="scene">
      <div class="wobble">
        <img class="idle-png" alt="" draggable="false" src="data:image/png;base64,"/>
        <div class="breathe">
          <svg class="face" viewBox="0 0 512 512" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
            <g class="look">
              <!-- left eye -->
              <circle cx="169" cy="198" r="14.4" fill="#F7F4FF"/>
              <circle cx="169" cy="198" r="6.2" fill="#1A1228"/>
              <ellipse class="lid" cx="169" cy="198" rx="14.4" ry="14.4" fill="#2A1E3A"/>
              <!-- right eye -->
              <circle cx="292" cy="198" r="14.4" fill="#F7F4FF"/>
              <circle cx="292" cy="198" r="6.2" fill="#1A1228"/>
              <ellipse class="lid" cx="292" cy="198" rx="14.4" ry="14.4" fill="#2A1E3A"/>
              <!-- glasses -->
              <circle cx="169" cy="198" r="31.1" fill="none" stroke="rgba(30,22,48,0.92)" stroke-width="2.4"/>
              <circle cx="292" cy="198" r="32.4" fill="none" stroke="rgba(30,22,48,0.92)" stroke-width="2.4"/>
              <path d="M200 190 C220 174 240 174 260 190" fill="none" stroke="rgba(30,22,48,0.92)" stroke-width="2.2" stroke-linecap="round"/>
            </g>
            <!-- mouth -->
            <ellipse class="mouth" cx="230" cy="268" rx="39" ry="6" fill="rgba(40,30,50,0.55)"/>
          </svg>
          <div class="gimbal">
            <div class="ring-spin">
              <svg class="gas-svg" viewBox="-100 -100 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <defs>
                  <radialGradient id="gasGlow" cx="50%" cy="50%" r="50%">
                    <stop offset="0%" stop-color="#9AF7FF" stop-opacity="0.9"/>
                    <stop offset="55%" stop-color="#9AF7FF" stop-opacity="0.35"/>
                    <stop offset="100%" stop-color="#9AF7FF" stop-opacity="0"/>
                  </radialGradient>
                </defs>
                <!-- trail beads on ellipse (squash ≈ cos 26°) -->
                <g fill="#9AF7FF">
                  <circle cx="90" cy="0" r="7" opacity="0.08"/>
                  <circle cx="78" cy="-20" r="6" opacity="0.12"/>
                  <circle cx="58" cy="-38" r="5.2" opacity="0.2"/>
                  <circle cx="32" cy="-50" r="4.4" opacity="0.32"/>
                  <circle cx="2" cy="-54" r="3.6" opacity="0.45"/>
                  <circle cx="-28" cy="-48" r="2.8" opacity="0.28"/>
                  <circle cx="-52" cy="-34" r="2.1" opacity="0.16"/>
                  <circle cx="-68" cy="-14" r="1.5" opacity="0.08"/>
                </g>
                <ellipse cx="0" cy="0" rx="92" ry="82.7" fill="url(#gasGlow)" opacity="0.25"/>
              </svg>
              <div class="billboard"></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</body>
</html>
`;

/** Full host document with mark size (px) and working morph class. */
export function softV8bHostDocument(size: number, isOn: boolean): string {
  const s = Math.max(1, Math.round(size));
  const onClass = isOn ? ' is-on' : '';
  return SOFT_V8B_HOST_HTML.replace(
    '<div class="av" id="soft-root">',
    `<div class="av${onClass}" id="soft-root" style="--s:${s}px">`,
  );
}

/** Inner markup only (web DOM host) — style + body of the SoT host. */
export function softV8bHostInnerHtml(size: number, isOn: boolean): string {
  const doc = softV8bHostDocument(size, isOn);
  const styleMatch = doc.match(/<style>([\s\S]*?)<\/style>/);
  const bodyMatch = doc.match(/<body>([\s\S]*?)<\/body>/);
  const css = styleMatch?.[1] ?? '';
  const body = bodyMatch?.[1] ?? '';
  return `<style>${css}</style>${body}`;
}
